 5 namespace EarthBound
 6 {
 7     public class DualWriter : TextWriter
 8     {
 9         private TextWriter originalOut;
10         private StreamWriter fileOut;
11 
12         public DualWriter(string filePath)
13         {
14             originalOut = Console.Out;
15             fileOut = new StreamWriter(filePath, false, Encoding.UTF8) { AutoFlush = true };
16         }
17 
18         public override Encoding Encoding => originalOut.Encoding;
19 
20         public override void Write(char value)
21         {
22             originalOut.Write(value);
23             fileOut.Write(value);
24         }
25 
26         public override void Write(string value)
27         {
28             originalOut.Write(value);
29             fileOut.Write(value);
30         }
31 
32         public override void WriteLine(string? value)
33         {
34             string log = $"[{DateTime.Now:HH:mm:ss.fff}] {value}";
35             originalOut.WriteLine(log);
36             fileOut.WriteLine(log);
37         }
38 
39         protected override void Dispose(bool disposing)
40         {
41             if (disposing) fileOut.Dispose();
42             base.Dispose(disposing);
43         }
44     }
