 258         private static WindowIcon LoadWindowIcon(string path)
 259         {
 260             if (!File.Exists(path))
 261             {
 262                 Console.WriteLine($"[ICON ERROR] Файл не найден: {path}");
 263                 return null;
 264             }
 265 
 266             try
 267             {
 268                 // Используем System.Drawing.Bitmap (он умеет читать .ico)
 269                 using (var bitmap = new System.Drawing.Bitmap(path))
 270                 {
 271                     // Блокируем биты изображения для чтения
 272                     var data = bitmap.LockBits(
 273                         new System.Drawing.Rectangle(0, 0, bitmap.Width, bitmap.Height),
 274                         System.Drawing.Imaging.ImageLockMode.ReadOnly,
 275                         System.Drawing.Imaging.PixelFormat.Format32bppArgb);
 276 
 277                     int byteCount = data.Stride * data.Height;
 278                     byte[] bytes = new byte[byteCount];
 279 
 280                     // Копируем сырые байты из Bitmap в массив
 281                     System.Runtime.InteropServices.Marshal.Copy(data.Scan0, bytes, 0, byteCount);
 282 
 283                     bitmap.UnlockBits(data);
 284 
 285                     // ВАЖНО: System.Drawing грузит как BGRA, а OpenTK нужно RGBA.
 286                     // Меняем местами Синий (B) и Красный (R) каналы.
 287                     for (int i = 0; i < bytes.Length; i += 4)
 288                     {
 289                         byte b = bytes[i];
 290                         byte r = bytes[i + 2];
 291 
 292                         bytes[i] = r;     // R
 293                         bytes[i + 2] = b; // B
 294                     }
 295 
 296                     // Создаем картинку для OpenTK
 297                     var iconImage = new OpenTK.Windowing.Common.Input.Image(bitmap.Width, bitmap.Height, bytes);
 298                     return new WindowIcon(iconImage);
 299                 }
 300             }
 301             catch (Exception e)
 302             {
 303                 Console.WriteLine($"[ICON ERROR] Ошибка загрузки иконки: {e.Message}");
 304                 return null;
 305             }
 306         }
