 400         private void RenderFrameGraph()
 401         {
 402             uiRenderer.Prepare();
 403 
 404             float barWidth = 4.0f;
 405             float startX = 20.0f;
 406             float startY = Size.Y - 40.0f; // Рисуем снизу вверх
 407             float scaleY = 3.0f; // 1 миллисекунда = 3 пикселя на экране
 408 
 409             // Фон графика
 410             uiRenderer.DrawRect(startX - 5, startY - (50 * scaleY), (GRAPH_SIZE * barWidth) + 10, (50 * scaleY) + 5, new Vector3(0, 0, 0), 0.6f);
 411 
 412             for (int i = 0; i < GRAPH_SIZE; i++)
 413             {
 414                 int idx = (historyIndex + i) % GRAPH_SIZE;
 415                 float upd = historyUpdate[idx];
 416                 float rnd = historyRender[idx];
 417 
 418                 float x = startX + (i * barWidth);
 419 
 420                 // Защита от слишком длинных полосок
 421                 if (upd > 50f) upd = 50f;
 422                 if (rnd > 50f) rnd = 50f;
 423 
 424                 // Синяя полоска - Update (Логика)
 425                 float hUpd = upd * scaleY;
 426                 uiRenderer.DrawRect(x, startY - hUpd, barWidth - 1, hUpd, new Vector3(0.2f, 0.4f, 1.0f), 1.0f);
 427 
 428                 // Красная полоска - Render (Отрисовка) ставится поверх синей
 429                 float hRnd = rnd * scaleY;
 430                 uiRenderer.DrawRect(x, startY - hUpd - hRnd, barWidth - 1, hRnd, new Vector3(1.0f, 0.2f, 0.2f), 1.0f);
 431             }
 432 
 433             // Рисуем линию 60 FPS (16.6 мс)
 434             float y60 = startY - (16.6f * scaleY);
 435             uiRenderer.DrawRect(startX, y60, GRAPH_SIZE * barWidth, 2, new Vector3(0.0f, 1.0f, 0.0f), 0.8f);
 436 
 437             // Рисуем линию 30 FPS (33.3 мс)
 438             float y30 = startY - (33.3f * scaleY);
 439             uiRenderer.DrawRect(startX, y30, GRAPH_SIZE * barWidth, 2, new Vector3(1.0f, 1.0f, 0.0f), 0.8f);
 440 
 441             // Текст-пояснения
 442             textRenderer.UpdateText("60 FPS");
 443             textRenderer.Render(startX + (GRAPH_SIZE * barWidth) + 10, y60 - 8, 0.3f, uiRenderer.GetProjection());
 444 
 445             textRenderer.UpdateText("30 FPS");
 446             textRenderer.Render(startX + (GRAPH_SIZE * barWidth) + 10, y30 - 8, 0.3f, uiRenderer.GetProjection());
 447         }
 448         private Vector3 FindSafeSpawn()
 449         {
 450             // Ищем по спирали от центра мира
 451             for (int radius = 0; radius < 100; radius += 4)
 452             {
 453                 for (int x = -radius; x <= radius; x += 4)
 454                 {
 455                     for (int z = -radius; z <= radius; z += 4)
 456                     {
 457                         // Ищем только по периметру текущего квадрата
 458                         if (Math.Abs(x) != radius && Math.Abs(z) != radius) continue;
 459 
 460                         // Сканируем высоту (начиная выше уровня моря!)
 461                         for (int y = 120; y > TerrainGenerator.OceanLevel; y--)
 462                         {
 463                             BlockType b = world.GetBlock(new Vector3(x, y, z));
 464                             // Ищем твердый блок
 465                             if (b != BlockType.AIR && b != BlockType.WATER && b != BlockType.LEAVES && b != BlockType.LOG)
 466                             {
 467                                 BlockType up1 = world.GetBlock(new Vector3(x, y + 1, z));
 468                                 BlockType up2 = world.GetBlock(new Vector3(x, y + 2, z));
 469 
 470                                 // Если над нами 2 блока воздуха — место найдено!
 471                                 if (up1 == BlockType.AIR && up2 == BlockType.AIR)
 472                                 {
 473                                     return new Vector3(x + 0.5f, y + 1.5f, z + 0.5f);
 474                                 }
 475                             }
 476                         }
 477                     }
 478                 }
 479             }
 480             // Если вся загруженная зона — море, спавним высоко, парашют спасет
 481             return new Vector3(0.5f, 100f, 0.5f);
 482         }
