 668         protected override void OnUpdateFrame(FrameEventArgs args)
 669         {
 670             frameTimer.Restart();
 671             base.OnUpdateFrame(args);
 672             // --- FLOATING ORIGIN (ПЛАВАЮЩАЯ ТОЧКА ОТСЧЕТА) ---
 673             if (world != null && (CurrentState == GameState.Playing || CurrentState == GameState.DevMenu || isDebugCam))
 674             {
 675                 Vector3i shift = Vector3i.Zero;
 676                 int limit = 2000; // Уходим дальше 2000 - возвращаем мир в центр
 677 
 678                 if (camera.position.X > limit) shift.X = limit;
 679                 else if (camera.position.X < -limit) shift.X = -limit;
 680 
 681                 if (camera.position.Z > limit) shift.Z = limit;
 682                 else if (camera.position.Z < -limit) shift.Z = -limit;
 683 
 684                 if (shift != Vector3i.Zero)
 685                 {
 686                     camera.position -= new Vector3(shift.X, 0, shift.Z);
 687                     camera.ResetFallState();
 688                     if (isDebugCam) debugCamera.position -= new Vector3(shift.X, 0, shift.Z);
 689 
 690                     world.ShiftOrigin(shift);
 691                     weatherRenderer.ResetParticles();
 692                     cloudRenderer.CloudOffset.X -= shift.X;
 693                     cloudRenderer.CloudOffset.Y -= shift.Z;
 694                 }
 695             }
 696             bool isMenu = (CurrentState != GameState.Playing && CurrentState != GameState.Paused && CurrentState != GameState.InventoryOpen && CurrentState != GameState.Dead);
 697             audio.UpdateMusic((float)args.Time, isMenu, Settings.MusicVolume);
 698 
 699             // --- TICK SYSTEM LOGIC (С ЗАЩИТОЙ ОТ СПИРАЛИ СМЕРТИ) ---
 700             accumulatedTime += args.Time;
 701 
 702             // ФИКС: Если игра зависла (например, при загрузке или из-за винды), 
 703             // не пытаемся просчитать 500 тиков за раз. Сбрасываем лишнее время!
 704             if (accumulatedTime > 0.5)
 705             {
 706                 accumulatedTime = 0.5; // Максимум 10 тиков за один кадр
 707             }
 708 
 709             while (accumulatedTime >= TIME_PER_TICK)
 710             {
 711                 GameTick();
 712                 accumulatedTime -= TIME_PER_TICK;
 713             }
 714 
 715             // Подсчет FPS и TPS
 716             oneSecondTimer += args.Time;
 717             frames++;
 718             if (oneSecondTimer >= 1.0)
 719             {
 720                 fps = frames;
 721                 tps = tickCounter;
 722 
 723                 // ВОЗВРАЩАЕМ ВЫВОД В КОНСОЛЬ
 724                 double avgUpdate = frames > 0 ? totalUpdateTimeMs / frames : 0;
 725                 double avgRender = frames > 0 ? totalRenderTimeMs / frames : 0;
 726                 // Записываем статистику в advanced_log.txt раз в 5 сек
 727                 EarthBound.Diagnostics.AdvancedProfiler.Update(fps, tps, camera.position);
 728                 Console.WriteLine($"[PERFORMANCE] FPS: {fps} | TPS: {tps} | Update: {avgUpdate:0.00}ms | Render(CPU): {avgRender:0.00}ms");
 729 
 730                 totalUpdateTimeMs = 0;
 731                 totalRenderTimeMs = 0;
 732                 totalChunkUpdateTimeMs = 0;
 733 
 734                 frames = 0;
 735                 tickCounter = 0;
 736                 oneSecondTimer = 0;
 737             }
 738 
 739             // Переключение графиков
 740             if (KeyboardState.IsKeyPressed(Keys.F3)) showDebugInfo = !showDebugInfo;
 741             if (KeyboardState.IsKeyPressed(Keys.F1)) showFrameGraph = !showFrameGraph; // Переназначено на F1!
 742             if (KeyboardState.IsKeyPressed(Keys.F8)) showWindDebug = !showWindDebug;   // Свободно для радара ветра!
 743             if (KeyboardState.IsKeyPressed(Keys.F7)) showPerfOverlay = !showPerfOverlay;
 744             if (KeyboardState.IsKeyPressed(Keys.F11) && Settings.DevModeEnabled) showNetworkOverlay = !showNetworkOverlay;
 745             if (KeyboardState.IsKeyPressed(Keys.F4) && Settings.DevModeEnabled)
 746             {
 747                 camera.position = new Vector3(camera.position.X, 240, camera.position.Z);
 748                 camera.velocity = Vector3.Zero;
 749                 camera.ResetFallState();
 750                 isBurning = false;
 751                 burnTimer = 0;
 752             }
 753             if (KeyboardState.IsKeyPressed(Keys.F5) && Settings.DevModeEnabled)
 754                 showWireframe = !showWireframe;
 755             if (KeyboardState.IsKeyPressed(Keys.F6) && Settings.DevModeEnabled)
 756                 showChunkBorders = !showChunkBorders;
 757             if (KeyboardState.IsKeyPressed(Keys.F9) && Settings.DevModeEnabled)
 758             {
 759                 // 1. Перекомпилируем все шейдеры с диска
 760                 shader.Reload("Default.vert", "Default.frag");
 761                 cloudShader.Reload("Clouds.vert", "Clouds.frag");
 762                 weatherShader.Reload("Weather.vert", "Weather.frag");
 763                 solidShader.Reload("Default.vert", "Solid.frag");
 764 
 765                 // Сбрасываем кеш локаций в WorldClass
 766                 world?.ResetUniformCache();
 767 
 768                 // 2. Ребилдим все меши чанков
 769                 if (world != null)
 770                 {
 771                     foreach (var c in world.Chunks.Values)
 772                         world.QueueUpdatePublic(c.Coord);
 773                 }
 774 
 775                 notifSystem.Add("Dev", "Shaders recompiled + chunks rebuilt", NotifIcon.Success);
 776             }
 777             if (KeyboardState.IsKeyPressed(Keys.F12) && Settings.DevModeEnabled)
 778             {
 779                 EarthBound.Diagnostics.AdvancedProfiler.Toggle();
 780                 notifSystem.Add("Dev", "Advanced Profiler " + (EarthBound.Diagnostics.AdvancedProfiler.IsRecording ? "STARTED" : "STOPPED"), NotifIcon.Warning);
 781             }
 782             // --- DEV MENU TOGGLE (F2) ---
 783             if (KeyboardState.IsKeyPressed(Keys.F2) && Settings.DevModeEnabled)
 784             {
 785                 if (CurrentState == GameState.Playing)
 786                 {
 787                     CurrentState = GameState.DevMenu;
 788                     CursorState = CursorState.Normal;
 789                 }
 790                 else if (CurrentState == GameState.DevMenu)
 791                 {
 792                     CurrentState = GameState.Playing;
 793                     CursorState = CursorState.Grabbed;
 794                     camera.ResetMouse();
 795                 }
 796             }
 797 
 798             // --- КНОПКА СПАСЕНИЯ (F4) - ТОЛЬКО DEV MODE ---
 799             if (KeyboardState.IsKeyPressed(Keys.F4) && Settings.DevModeEnabled)
 800             {
 801                 camera.position = new Vector3(camera.position.X, 240, camera.position.Z);
 802                 camera.velocity = Vector3.Zero;
 803                 camera.ResetFallState();
 804                 isBurning = false;
 805                 burnTimer = 0;
 806             }
 807 
 808 
 809             float dt = (float)args.Time;
 810             _lastDt = dt;
 811             multiplayerClient?.Pump();
 812 
 813             if (handSwing > 0)
 814             {
 815                 handSwing -= dt * 5.0f;
 816                 if (handSwing < 0) handSwing = 0;
 817             }
 818 
 819             // 1. Плавное следование за скоростью падения (с лимитом)
 820             float targetVelY = MathHelper.Clamp(camera.velocity.Y, -25f, 15f);
 821             smoothHandVelocityY = MathHelper.Lerp(smoothHandVelocityY, targetVelY, dt * 8.0f);
 822 
 823             // 2. Инерция отставания руки при повороте камеры
 824             float deltaYaw = camera.rawRotation.Y - lastCameraRot.Y;
 825             float deltaPitch = camera.rawRotation.X - lastCameraRot.X;
 826 
 827             if (deltaYaw > 180) deltaYaw -= 360;
 828             if (deltaYaw < -180) deltaYaw += 360;
 829 
 830             lastCameraRot = camera.rawRotation;
 831 
 832             handSwayX = MathHelper.Lerp(handSwayX, MathHelper.Clamp(deltaYaw * 0.015f, -0.1f, 0.1f), dt * 12.0f);
 833             handSwayY = MathHelper.Lerp(handSwayY, MathHelper.Clamp(deltaPitch * 0.015f, -0.1f, 0.1f), dt * 12.0f);
 834 
 835             // Возврат руки в центр
 836             handSwayX = MathHelper.Lerp(handSwayX, 0, dt * 6.0f);
 837             handSwayY = MathHelper.Lerp(handSwayY, 0, dt * 6.0f);
 838 
 839             // Inventory logic
 840             if (CurrentState == GameState.InventoryOpen)
 841             {
 842                 HandleInventoryInput();
 843             }
 844 
 845             switch (CurrentState)
 846             {
 847                 case GameState.Loading:
 848                     UpdateLoading();
 849                     break;
 850                 case GameState.TomolkaOpen:
 851                     if (KeyboardState.IsKeyPressed(Keys.Escape) || KeyboardState.IsKeyPressed(Keys.E))
 852                     {
 853                         if (tomolkaInput != null) { world.SpawnItem(camera.position, tomolkaInput.Type, tomolkaInput.Count); tomolkaInput = null; }
 854                         if (tomolkaOutput != null)
 855                         {
 856                             var dropped = new ItemEntity(camera.position, tomolkaOutput.Type, tomolkaOutput.Count);
 857                             dropped.Volume = tomolkaOutput.Volume; // Обязательно сохраняем объем мешка при выходе
 858                             world.ItemEntities.Add(dropped);
 859                             tomolkaOutput = null;
 860                         }
 861                         CurrentState = GameState.Playing;
 862                         CursorState = CursorState.Grabbed;
 863                         camera.ResetMouse();
 864                     }
 865 
 866                     float dt_t = (float)args.Time;
 867                     if (dt_t > 0.1f) dt_t = 0.1f;
 868                     var mouse_t = MouseState;
 869                     Vector2 mPos = mouse_t.Position;
 870 
 871                     float sw = Size.X; float sh = Size.Y;
 872                     float cx = sw / 2; float cy = sh / 2;
 873                     float millRadius = 160f;
 874                     float handleRadius = 25f;
 875 
 876                     // 1. АВТО-ЗАГРУЗКА СЕМЯН
 877                     if (tomolkaInput != null && tomolkaInput.Type == BlockType.WHEAT_SEED)
 878                     {
 879                         t_seedsInside += tomolkaInput.Count * 25f;
 880                         tomolkaInput = null;
 881                         audio.PlayPlaceSound(BlockType.DIRT, camera.position);
 882                     }
 883                     else if (tomolkaInput != null)
 884                     {
 885                         world.SpawnItem(camera.position, tomolkaInput.Type, tomolkaInput.Count);
 886                         tomolkaInput = null;
 887                     }
 888 
 889                     // 2. ВРАЩЕНИЕ И ИНЕРЦИЯ (УВЕЛИЧЕНО СОПРОТИВЛЕНИЕ)
 890                     Vector2 handlePos = new Vector2(
 891                         cx + MathF.Cos(t_millRotation) * (millRadius - 30f),
 892                         cy + MathF.Sin(t_millRotation) * (millRadius - 30f)
 893                     );
 894 
 895                     bool hoverHandle = Vector2.Distance(mPos, handlePos) < handleRadius * 1.5f;
 896 
 897                     if (mouse_t.IsButtonPressed(MouseButton.Left) && hoverHandle)
 898                     {
 899                         t_draggingHandle = true;
 900                         t_prevAngle = MathF.Atan2(mPos.Y - cy, mPos.X - cx);
 901                     }
 902                     if (mouse_t.IsButtonReleased(MouseButton.Left)) t_draggingHandle = false;
 903 
 904                     if (t_draggingHandle)
 905                     {
 906                         float currAngle = MathF.Atan2(mPos.Y - cy, mPos.X - cx);
 907                         float deltaAngle = currAngle - t_prevAngle;
 908                         if (deltaAngle > MathF.PI) deltaAngle -= 2 * MathF.PI;
 909                         if (deltaAngle < -MathF.PI) deltaAngle += 2 * MathF.PI;
 910 
 911                         t_millVelocity = deltaAngle / dt_t;
 912                         t_prevAngle = currAngle;
 913                     }
 914 
 915                     // Применяем инерцию и СИЛЬНОЕ трение (0.85f вместо 0.95f)
 916                     t_millRotation += t_millVelocity * dt_t;
 917                     t_millVelocity *= 0.85f;
 918 
 919                     float rotationSpeed = MathF.Abs(t_millVelocity);
 920 
 921                     // 3. ПОМОЛ МУКИ
 922                     if (rotationSpeed > 0.5f && t_seedsInside > 0)
 923                     {
 924                         float grindAmount = rotationSpeed * dt_t * 12.0f;
 925                         grindAmount = Math.Min(grindAmount, t_seedsInside);
 926 
 927                         t_seedsInside -= grindAmount;
 928                         t_flourInside += grindAmount * 0.4f;
 929                         float spillAmount = grindAmount * 0.6f;
 930 
 931                         if (spillAmount > 0 && new Random().NextDouble() < 0.4)
 932                         {
 933                             float spawnAngle = (float)new Random().NextDouble() * MathF.PI * 2;
 934                             float spawnDist = millRadius + 5f + (float)new Random().NextDouble() * 50f;
 935 
 936                             t_splats.Add(new FlourSplat
 937                             {
 938                                 Pos = new Vector2(cx + MathF.Cos(spawnAngle) * spawnDist, cy + MathF.Sin(spawnAngle) * spawnDist),
 939                                 Size = 15f + (float)new Random().NextDouble() * 30f,
 940                                 Rotation = (float)new Random().NextDouble() * MathF.PI * 2f,
 941                                 Amount = spillAmount * 4f
 942                             });
 943                         }
 944 
 945                         t_grindSoundTimer -= dt_t;
 946                         if (t_grindSoundTimer <= 0)
 947                         {
 948                             float pitch = Math.Clamp(0.5f + (rotationSpeed / 15f), 0.6f, 1.8f);
 949                             float volume = Math.Clamp(rotationSpeed / 10f, 0.1f, 1.0f);
 950                             audio.PlayUISound("assets/audio/footsteps/stone/1.ogg", pitch, volume * 0.6f);
 951                             t_grindSoundTimer = 0.25f / Math.Max(1f, rotationSpeed * 0.3f);
 952                         }
 953                     }
 954 
 955                     // 4. СБОР МУКИ (СТРОГО ТОЛЬКО В МЕШОК)
 956                     bool isCollecting = mouse_t.IsButtonDown(MouseButton.Left) && !t_draggingHandle;
 957 
 958                     // Жесткая проверка: собираем ТОЛЬКО если есть мешок
 959                     bool hasSack = tomolkaOutput != null && tomolkaOutput.Type == BlockType.LEATHER_SACK;
 960                     int spaceLeft = hasSack ? (5700 - tomolkaOutput.Volume) : 0;
 961 
 962                     if (isCollecting && hasSack && spaceLeft > 0)
 963                     {
 964                         float mouseSpeed = mouse_t.Delta.Length / dt_t;
 965                         bool collectedSomething = false;
 966 
 967                         for (int i = t_splats.Count - 1; i >= 0; i--)
 968                         {
 969                             var splat = t_splats[i];
 970                             // Чуть увеличил радиус сбора, чтобы не надо было пиксельхантерством заниматься
 971                             if (Vector2.Distance(mPos, splat.Pos) < splat.Size + 40f)
 972                             {
 973                                 float collectRate = 400f * dt_t;
 974                                 float grabbed = Math.Min(collectRate, splat.Amount);
 975                                 grabbed = Math.Min(grabbed, spaceLeft - t_flourFraction);
 976 
 977                                 if (grabbed > 0)
 978                                 {
 979                                     splat.Amount -= grabbed;
 980                                     splat.Size -= grabbed * 0.15f;
 981                                     t_flourFraction += grabbed;
 982                                     collectedSomething = true;
 983                                 }
 984 
 985                                 if (splat.Amount <= 0 || splat.Size <= 0) t_splats.RemoveAt(i);
 986                             }
 987                         }
 988 
 989                         if (collectedSomething)
 990                         {
 991                             int wholeFlour = (int)t_flourFraction;
 992                             if (wholeFlour > 0)
 993                             {
 994                                 tomolkaOutput.Volume += wholeFlour;
 995                                 t_flourFraction -= wholeFlour;
 996                             }
 997 
 998                             t_powderSoundTimer -= dt_t;
 999                             if (t_powderSoundTimer <= 0)
1000                             {
1001                                 float pitch = Math.Clamp(0.8f + (mouseSpeed / 2000f), 0.8f, 1.5f);
1002                                 float volume = Math.Clamp(mouseSpeed / 800f, 0.2f, 1.0f);
1003                                 audio.PlayUISound("assets/audio/sfx/garden/powder.ogg", pitch, volume);
1004                                 t_powderSoundTimer = 0.4f;
1005                             }
1006                         }
1007                     }
1008                     else
1009                     {
1010                         t_powderSoundTimer = 0f;
1011                     }
1012 
1013                     HandleTomolkaInventoryInput();
1014                     break;
1015 
1016                 case GameState.Playing:
1017                     if (IsFocused && CursorState == CursorState.Grabbed)
1018                     {
1019                         // Check Fall Damage from Camera
1020                         // 1. Урон от падения
1021                         if (camera.PendingDamage > 0)
1022                         {
1023                             ApplyDamage(camera.PendingDamage);
1024                             camera.PendingDamage = 0;
1025 
1026                             if (playerHealth <= 0)
1027                             {
1028                                 playerHealth = 0;
1029                                 CurrentState = GameState.Dead;
1030                                 CursorState = CursorState.Normal;
1031                             }
1032                         }
1033 
1034                         // --- ВОДА И ВСПЛЕСКИ (Теперь всегда проверяется!) ---
