2081             float panelX = (ClientSize.X - panelW) / 2;
2082             float panelY = (ClientSize.Y - panelH) / 2;
2083 
2084             // 1. Координаты Инвентаря
2085             float gridStartX = panelX + (7 * scale);
2086             float gridStartY = panelY + (83 * scale);
2087             float hbY = panelY + (141 * scale);
