2089             // 2. Координаты Крафта (СОВПАДАЮТ С UIRenderer)
2090             float craftX, craftY;
2091 
2092             if (isWorkbench)
2093             {
2094                 // Для верстака (3x3)
2095                 craftX = panelX + (30 * scale);
2096                 craftY = panelY + (16 * scale);
2097             }
2098             else
2099             {
2100                 // Для инвентаря (2x2) - СДВИНУЛ ВЛЕВО (30 вместо 98)
2101                 craftX = panelX + (30 * scale);
2102                 craftY = panelY + (18 * scale);
2103             }
2104 
2105             // 3. Координаты Результата
2106             // Если это верстак, стрелка чуть дальше, если инвентарь - ближе
2107             float arrowXOffset = (isWorkbench) ? (3 * slotSize) + (10 * scale) : (2.5f * slotSize);
2108             float arrowX = craftX + arrowXOffset;
2109 
2110             float resX = arrowX + (25 * scale);
2111 
2112             // Подгонка высоты
2113             float resY;
2114             if (isWorkbench) resY = craftY + (1.0f * slotSize) - (2 * scale);
2115             else resY = craftY + (0.5f * slotSize) + (2 * scale); // +2 scale matching the render tweak
2116 
2117             // --- ХИТ ТЕСТ (КЛИКИ) ---
2118             Vector2 m = MouseState.Position;
2119             int hoveredType = -1; // 0=Inv, 1=Craft, 2=Result
2120             int hoveredIndex = -1;
2121 
2122             // Inv Main
2123             for (int i = 9; i < 36; i++)
2124             {
2125                 int r = (i - 9) / 9; int c = (i - 9) % 9;
2126                 float sx = gridStartX + c * slotSize;
2127                 float sy = gridStartY + r * slotSize;
2128                 if (m.X >= sx && m.X < sx + slotSize && m.Y >= sy && m.Y < sy + slotSize) { hoveredType = 0; hoveredIndex = i; }
2129             }
2130             // Inv Hotbar
2131             for (int i = 0; i < 9; i++)
2132             {
2133                 float sx = gridStartX + i * slotSize;
2134                 float sy = hbY;
2135                 if (m.X >= sx && m.X < sx + slotSize && m.Y >= sy && m.Y < sy + slotSize) { hoveredType = 0; hoveredIndex = i; }
2136             }
2137 
2138             // Craft Grid
2139             for (int y = 0; y < craftW; y++)
2140             {
2141                 for (int x = 0; x < craftW; x++)
2142                 {
2143                     int idx = y * craftW + x;
2144                     float sx = craftX + x * slotSize;
2145                     float sy = craftY + y * slotSize;
2146                     if (m.X >= sx && m.X < sx + slotSize && m.Y >= sy && m.Y < sy + slotSize) { hoveredType = 1; hoveredIndex = idx; }
2147                 }
2148             }
2149 
2150             // Result Slot
2151             if (m.X >= resX && m.X < resX + slotSize && m.Y >= resY && m.Y < resY + slotSize) { hoveredType = 2; hoveredIndex = 0; }
2152 
2153             // --- ЛОГИКА (Нажатия) ---
2154             bool leftClick = MouseState.IsButtonPressed(MouseButton.Left);
2155             bool rightClick = MouseState.IsButtonPressed(MouseButton.Right);
2156 
2157             if (leftClick || rightClick)
2158             {
2159                 if (hoveredType == 0) // Inventory
2160                 {
2161                     audio.PlayClick(); // ЗВУК ТУТ
2162                     ProcessSlotClick(inventory.Slots, hoveredIndex, leftClick, rightClick);
2163                 }
2164                 else if (hoveredType == 1) // Craft Grid
2165                 {
2166                     audio.PlayClick(); // ЗВУК ТУТ
2167                     ProcessSlotClick(inventory.CraftingGrid, hoveredIndex, leftClick, rightClick);
2168                     inventory.CraftResult = CraftingSystem.CheckRecipe(inventory.CraftingGrid, craftW);
2169                 }
2170                 else if (hoveredType == 2 && inventory.CraftResult != null) // Result
2171                 {
2172                     if (leftClick || rightClick)
2173                     {
2174                         audio.PlayClick(); // ЗВУК ТУТ
2175 
2176                         if (inventory.DragStack == null ||
2177                            (inventory.DragStack.Type == inventory.CraftResult.Type &&
2178                             inventory.DragStack.Count + inventory.CraftResult.Count <= ItemStack.GetMaxStack(inventory.CraftResult.Type)))
2179                         {
2180                             if (inventory.DragStack == null)
2181                                 inventory.DragStack = new ItemStack(inventory.CraftResult.Type, inventory.CraftResult.Count);
2182                             else
2183                                 inventory.DragStack.Count += inventory.CraftResult.Count;
2184 
2185                             for (int i = 0; i < craftSize; i++)
2186                             {
2187                                 if (inventory.CraftingGrid[i] != null)
2188                                 {
2189                                     inventory.CraftingGrid[i].Count--;
2190                                     if (inventory.CraftingGrid[i].Count <= 0) inventory.CraftingGrid[i] = null;
2191                                 }
2192                             }
2193 
2194                             inventory.CraftResult = CraftingSystem.CheckRecipe(inventory.CraftingGrid, craftW);
2195                             audio.PlayPlaceSound(inventory.DragStack.Type, camera.position);
2196                         }
2197                     }
2198                 }
2199             }
2200 
2201             this.lastHoverType = hoveredType;
2202             this.lastHoverIdx = hoveredIndex;
2203         }
