2209         private void ProcessSlotClick(ItemStack[] array, int idx, bool isLeft, bool isRight)
2210         {
2211             if (idx < 0 || idx >= array.Length) return;
2212             ItemStack slot = array[idx];
2213             ItemStack hand = inventory.DragStack;
2214 
2215             if (isLeft)
2216             {
2217                 // ЛКМ: Свап / Взять / Положить всё
2218                 if (hand == null && slot != null)
2219                 {
2220                     inventory.DragStack = slot;
2221                     array[idx] = null;
2222                 }
2223                 else if (hand != null && slot == null)
2224                 {
2225                     array[idx] = hand;
2226                     inventory.DragStack = null;
2227                 }
2228                 else if (hand != null && slot != null)
2229                 {
2230                     if (hand.Type == slot.Type)
2231                     {
2232                         int space = ItemStack.GetMaxStack(slot.Type) - slot.Count;
2233                         int toAdd = Math.Min(space, hand.Count);
2234                         slot.Count += toAdd;
2235                         hand.Count -= toAdd;
2236                         if (hand.Count <= 0) inventory.DragStack = null;
2237                     }
2238                     else
2239                     {
2240                         // Swap
2241                         array[idx] = hand;
2242                         inventory.DragStack = slot;
2243                     }
2244                 }
2245             }
2246             else if (isRight)
2247             {
2248                 // ПКМ
2249                 if (hand == null && slot != null)
2250                 {
2251                     // Взять половину
2252                     int take = (int)Math.Ceiling(slot.Count / 2.0);
2253                     inventory.DragStack = new ItemStack(slot.Type, take);
2254                     slot.Count -= take;
2255                     if (slot.Count <= 0) array[idx] = null;
2256                 }
2257                 else if (hand != null)
2258                 {
2259                     // Положить ОДИН
2260                     if (slot == null)
2261                     {
2262                         array[idx] = new ItemStack(hand.Type, 1);
2263                         hand.Count--;
2264                         if (hand.Count <= 0) inventory.DragStack = null;
2265                     }
2266                     else if (slot.Type == hand.Type && slot.Count < ItemStack.GetMaxStack(slot.Type))
2267                     {
2268                         slot.Count++;
2269                         hand.Count--;
2270                         if (hand.Count <= 0) inventory.DragStack = null;
2271                     }
2272                 }
2273             }
2274         }
