3038         private void RenderSelectionOutline(Vector3i pos)
3039         {
3040             BlockType type = world.GetBlock(new Vector3(pos.X, pos.Y, pos.Z));
3041             byte data = world.GetBlockData(pos);
3042             var boxes = EarthBound.World.Blocks.BlocksManager.GetBlock(type).GetBoundingBoxes(data);
3043 
3044             if (type == BlockType.SNOW_LAYER)
3045             {
3046                 int layers = (data & 7) + 1;
3047                 boxes.Clear();
3048                 boxes.Add(new AABB(new Vector3(-0.5f, -0.5f, -0.5f), new Vector3(0.5f, -0.5f + (layers * 0.125f), 0.5f)));
3049             }
3050 
3051             if (boxes.Count == 0) return;
3052 
3053             List<Vector3> verts = new List<Vector3>();
3054             float expand = 0.002f;
3055 
3056             foreach (var box in boxes)
3057             {
3058                 float x1 = pos.X + box.Min.X - expand;
3059                 float y1 = pos.Y + box.Min.Y - expand;
3060                 float z1 = pos.Z + box.Min.Z - expand;
3061                 float x2 = pos.X + box.Max.X + expand;
3062                 float y2 = pos.Y + box.Max.Y + expand;
3063                 float z2 = pos.Z + box.Max.Z + expand;
3064 
3065                 // Линии каркаса
3066                 Vector3 p1 = new Vector3(x1, y1, z1); Vector3 p2 = new Vector3(x2, y1, z1);
3067                 Vector3 p3 = new Vector3(x2, y1, z2); Vector3 p4 = new Vector3(x1, y1, z2);
3068                 Vector3 p5 = new Vector3(x1, y2, z1); Vector3 p6 = new Vector3(x2, y2, z1);
3069                 Vector3 p7 = new Vector3(x2, y2, z2); Vector3 p8 = new Vector3(x1, y2, z2);
3070 
3071                 verts.AddRange(new[] { p1, p2, p2, p3, p3, p4, p4, p1 }); // Низ
3072                 verts.AddRange(new[] { p5, p6, p6, p7, p7, p8, p8, p5 }); // Верх
3073                 verts.AddRange(new[] { p1, p5, p2, p6, p3, p7, p4, p8 }); // Стойки
3074             }
3075 
3076             shader.Bind();
3077             GL.Uniform4(GL.GetUniformLocation(shader.ID, "overlayColor"), new Vector4(0, 0, 0, 1));
3078 
3079             outlineVAO.Bind();
3080             GL.BindBuffer(BufferTarget.ArrayBuffer, outlineVBO.ID);
3081             GL.BufferData(BufferTarget.ArrayBuffer, verts.Count * Vector3.SizeInBytes, verts.ToArray(), BufferUsageHint.StreamDraw);
3082 
3083             Matrix4 model = Matrix4.Identity;
3084             GL.UniformMatrix4(GL.GetUniformLocation(shader.ID, "model"), true, ref model);
3085 
3086             GL.LineWidth(2.5f);
3087             GL.DrawArrays(PrimitiveType.Lines, 0, verts.Count);
3088             GL.LineWidth(1.0f);
3089 
3090             outlineVAO.Unbind();
3091             GL.Uniform4(GL.GetUniformLocation(shader.ID, "overlayColor"), Vector4.Zero);
3092         }
