3684         private void LoadLicenses()
3685         {
3686             licenseFiles.Clear();
3687             if (!Directory.Exists("assets")) return;
3688 
3689             try
3690             {
3691                 var files = Directory.GetFiles("assets", "*.*", SearchOption.AllDirectories)
3692                     .Where(s => s.EndsWith(".txt") || s.ToLower().Contains("license"));
3693 
3694                 foreach (var f in files)
3695                 {
3696                     string content = File.ReadAllText(f);
3697 
3698                     // Делаем красивое имя: "footsteps / grass / license.txt"
3699                     // Берем имя папки, в которой лежит файл, и имя файла
3700                     DirectoryInfo parent = Directory.GetParent(f);
3701                     string displayTitle = $"{parent.Name} / {Path.GetFileName(f)}";
3702 
3703                     licenseFiles.Add(new LicenseFile { Name = displayTitle, Path = f, Content = content });
3704                 }
3705             }
3706             catch { }
3707         }
