3974         private void PerformSaveAndExit()
3975         {
3976             // Очищаем GPU буферы сущностей и предметов перед удалением мира
3977             if (world != null)
3978             {
3979                 foreach (var item in world.ItemEntities) item.Delete();
3980                 foreach (var ent in world.Entities)
3981                 {
3982                     if (ent is SlimeEntity slime) slime.Delete();
3983                     else if (ent is TntEntity tnt) tnt.Delete();
3984                     else if (ent is FallingBlockEntity fb) fb.Delete();
