4084         private void RenderBreakOverlay(Vector3i pos, int stage)
4085         {
4086             if (stage < 0 || stage >= TextureData.BreakLayerIndices.Count) return;
4087             int layer = TextureData.BreakLayerIndices[stage];
4088 
4089             BlockType type = world.GetBlock(new Vector3(pos.X, pos.Y, pos.Z));
4090             byte data = world.GetBlockData(pos);
4091             var boxes = EarthBound.World.Blocks.BlocksManager.GetBlock(type).GetBoundingBoxes(data);
4092 
4093             if (type == BlockType.SNOW_LAYER)
4094             {
4095                 int layers = (data & 7) + 1;
4096                 boxes.Clear();
4097                 boxes.Add(new AABB(new Vector3(-0.5f, -0.5f, -0.5f), new Vector3(0.5f, -0.5f + (layers * 0.125f), 0.5f)));
4098             }
4099 
4100             List<Vector3> verts = new List<Vector3>();
4101             List<Vector3> uvs = new List<Vector3>();
4102             List<Vector3> colors = new List<Vector3>();
4103             List<Vector2> lights = new List<Vector2>();
4104 
4105             float expand = 0.003f;
4106 
4107             foreach (var box in boxes)
4108             {
4109                 float x1 = pos.X + box.Min.X - expand; float y1 = pos.Y + box.Min.Y - expand; float z1 = pos.Z + box.Min.Z - expand;
4110                 float x2 = pos.X + box.Max.X + expand; float y2 = pos.Y + box.Max.Y + expand; float z2 = pos.Z + box.Max.Z + expand;
4111 
4112                 // Добавляем 6 граней для каждой коробки
4113                 AddCrackFace(verts, uvs, x1, y1, z2, x2, y1, z2, x2, y2, z2, x1, y2, z2, layer); // Front
4114                 AddCrackFace(verts, uvs, x2, y1, z1, x1, y1, z1, x1, y2, z1, x2, y2, z1, layer); // Back
4115                 AddCrackFace(verts, uvs, x1, y1, z1, x1, y1, z2, x1, y2, z2, x1, y2, z1, layer); // Left
4116                 AddCrackFace(verts, uvs, x2, y1, z2, x2, y1, z1, x2, y2, z1, x2, y2, z2, layer); // Right
4117                 AddCrackFace(verts, uvs, x1, y2, z2, x2, y2, z2, x2, y2, z1, x1, y2, z1, layer); // Top
4118                 AddCrackFace(verts, uvs, x1, y1, z1, x2, y1, z1, x2, y1, z2, x1, y1, z2, layer); // Bottom
4119             }
4120 
4121             for (int i = 0; i < verts.Count; i++) { colors.Add(Vector3.One); lights.Add(new Vector2(15, 15)); }
4122 
4123             crackVAO.Bind();
4124             GL.BindBuffer(BufferTarget.ArrayBuffer, crackVBO.ID);
4125             GL.BufferData(BufferTarget.ArrayBuffer, verts.Count * Vector3.SizeInBytes, verts.ToArray(), BufferUsageHint.StreamDraw);
4126             GL.BindBuffer(BufferTarget.ArrayBuffer, crackUV.ID);
4127             GL.BufferData(BufferTarget.ArrayBuffer, uvs.Count * Vector3.SizeInBytes, uvs.ToArray(), BufferUsageHint.StreamDraw);
4128             GL.BindBuffer(BufferTarget.ArrayBuffer, crackColor.ID);
4129             GL.BufferData(BufferTarget.ArrayBuffer, colors.Count * Vector3.SizeInBytes, colors.ToArray(), BufferUsageHint.StreamDraw);
4130             GL.BindBuffer(BufferTarget.ArrayBuffer, crackLight.ID);
4131             GL.BufferData(BufferTarget.ArrayBuffer, lights.Count * Vector2.SizeInBytes, lights.ToArray(), BufferUsageHint.StreamDraw);
4132 
4133             shader.Bind();
4134             Matrix4 model = Matrix4.Identity;
4135             GL.UniformMatrix4(GL.GetUniformLocation(shader.ID, "model"), true, ref model);
4136             globalTextureArray.Bind();
4137             GL.Uniform1(GL.GetUniformLocation(shader.ID, "isCrack"), 1);
4138 
4139             GL.DrawArrays(PrimitiveType.Triangles, 0, verts.Count);
4140 
4141             crackVAO.Unbind();
4142             GL.Uniform1(GL.GetUniformLocation(shader.ID, "isCrack"), 0);
4143         }
