4161         private string FitTextToWidth(string text, float maxWidth, float scale)
4162         {
4163             if (string.IsNullOrEmpty(text)) return "";
4164 
4165             // Примерная ширина одного символа (зависит от шрифта TextRenderer)
4166             // У нас моноширинный шрифт, базовая ширина ~14-15 пикселей.
4167             float charWidth = 15.0f * scale;
4168 
4169             int maxChars = (int)(maxWidth / charWidth);
4170 
4171             if (text.Length <= maxChars) return text;
4172 
4173             // Если текст длиннее, обрезаем и добавляем "..."
4174             return text.Substring(0, Math.Max(0, maxChars - 3)) + "...";
4175         }
